function adjust(data,w,h,a){if(!a)return data;const angle=a.hue*Math.PI/180,cs=Math.cos(angle),sn=Math.sin(angle),contrast=a.contrast/100,sat=a.saturation/100;for(let i=0;i<data.length;i+=4){if(data[i+3]<100)continue;let r=data[i],g=data[i+1],b=data[i+2];let nr=(.213+.787*cs-.213*sn)*r+(.715-.715*cs-.715*sn)*g+(.072-.072*cs+.928*sn)*b,ng=(.213-.213*cs+.143*sn)*r+(.715+.285*cs+.140*sn)*g+(.072-.072*cs-.283*sn)*b,nb=(.213-.213*cs-.787*sn)*r+(.715-.715*cs+.715*sn)*g+(.072+.928*cs+.072*sn)*b;const gray=.2126*nr+.7152*ng+.0722*nb;[nr,ng,nb].forEach((v,k)=>data[i+k]=Math.max(0,Math.min(255,((gray+(v-gray)*sat)*a.brightness/100-128)*contrast+128)))}if(a.sharpness){const old=data.slice(),amount=a.sharpness/100;for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){let i=(y*w+x)*4;if(old[i+3]<100)continue;const ns=[i-4,i+4,i-w*4,i+w*4].filter(j=>old[j+3]>=100);if(!ns.length)continue;for(let k=0;k<3;k++)data[i+k]=Math.max(0,Math.min(255,old[i+k]+amount*(old[i+k]-ns.reduce((s,j)=>s+old[j+k],0)/ns.length)))}}return data}
function lab(rgb){let [r,g,b]=rgb.map(v=>{v/=255;return v>.04045?Math.pow((v+.055)/1.055,2.4):v/12.92});let xyz=[(r*.4124564+g*.3575761+b*.1804375)/.95047,(r*.2126729+g*.7151522+b*.072175),(r*.0193339+g*.119192+b*.9503041)/1.08883].map(v=>v>.008856?Math.cbrt(v):7.787*v+16/116);return [116*xyz[1]-16,500*(xyz[0]-xyz[1]),200*(xyz[1]-xyz[2])]}
// CIEDE2000, D65 Lab. All angular values below are degrees.
function de(a,b){const rad=Math.PI/180,atan=(y,x)=>(Math.atan2(y,x)/rad+360)%360;let [L1,a1,b1]=a,[L2,a2,b2]=b;let C1=Math.hypot(a1,b1),C2=Math.hypot(a2,b2),cm=(C1+C2)/2,G=.5*(1-Math.sqrt(cm**7/(cm**7+25**7)));a1*=1+G;a2*=1+G;C1=Math.hypot(a1,b1);C2=Math.hypot(a2,b2);let h1=atan(b1,a1),h2=atan(b2,a2),dl=L2-L1,dc=C2-C1,dh=h2-h1;if(C1*C2===0)dh=0;else if(dh>180)dh-=360;else if(dh< -180)dh+=360;let dH=2*Math.sqrt(C1*C2)*Math.sin(dh*rad/2),lm=(L1+L2)/2;cm=(C1+C2)/2;let hm=C1*C2===0?h1+h2:Math.abs(h1-h2)<=180?(h1+h2)/2:(h1+h2+(h1+h2<360?360:-360))/2;let T=1-.17*Math.cos((hm-30)*rad)+.24*Math.cos(2*hm*rad)+.32*Math.cos((3*hm+6)*rad)-.2*Math.cos((4*hm-63)*rad);let sl=1+.015*(lm-50)**2/Math.sqrt(20+(lm-50)**2),sc=1+.045*cm,sh=1+.015*cm*T,rt=-2*Math.sqrt(cm**7/(cm**7+25**7))*Math.sin(60*Math.exp(-1*((hm-275)/25)**2)*rad);return Math.sqrt((dl/sl)**2+(dc/sc)**2+(dH/sh)**2+rt*(dc/sc)*(dH/sh))}
onmessage=({data:o})=>{try{const {w,h,palette,limit,dither,denoise}=o;const data=adjust(new Float32Array(o.pixels),w,h,o.adjust),rgb=palette.map(c=>c.hex.slice(1).match(/../g).map(x=>parseInt(x,16))),labs=rgb.map(lab),cache=new Map();const nearest=(r,g,b,ids)=>{const key=`${Math.round(r)},${Math.round(g)},${Math.round(b)}:${ids.length}`;if(cache.has(key))return cache.get(key);const l=lab([r,g,b]);const candidates=ids.map(i=>[i,l.reduce((s,v,j)=>s+(v-labs[i][j])**2,0)]).sort((a,b)=>a[1]-b[1]).slice(0,12);let best=-1,dist=Infinity;for(const [i] of candidates){const d=de(l,labs[i]);if(d<dist){dist=d;best=i}}cache.set(key,best);return best};let ids=palette.map((_,i)=>i),cells=[],freq={};for(let i=0;i<w*h;i++){let v=data[i*4+3]<100?-1:nearest(...data.slice(i*4,i*4+3),ids);cells.push(v);if(v>=0)freq[v]=(freq[v]||0)+1}postMessage({progress:40});if(limit&&Object.keys(freq).length>limit){ids=Object.keys(freq).sort((a,b)=>freq[b]-freq[a]).slice(0,limit).map(Number);cache.clear();cells=cells.map((v,i)=>v<0?-1:nearest(...data.slice(i*4,i*4+3),ids))}if(denoise){const old=[...cells];for(let y=1;y<h-1;y++)for(let x=1;x<w-1;x++){let i=y*w+x;if(old[i]<0)continue;const ns=[old[i-1],old[i+1],old[i-w],old[i+w]];if(ns.every(v=>v===ns[0])&&ns[0]>=0)cells[i]=ns[0]}}
if(limit){ids=[...new Set(cells.filter(v=>v>=0))];cache.clear()}postMessage({progress:65});if(dither!=='none'){cache.clear();for(let y=0;y<h;y++)for(let x=0;x<w;x++){let i=y*w+x;if(cells[i]<0)continue;let v=nearest(...data.slice(i*4,i*4+3),ids);cells[i]=v;const steps=dither==='atkinson'?[[1,0,1/8],[2,0,1/8],[-1,1,1/8],[0,1,1/8],[1,1,1/8],[0,2,1/8]]:[[1,0,7/16],[-1,1,3/16],[0,1,5/16],[1,1,1/16]];for(const [dx,dy,f] of steps){let xx=x+dx,yy=y+dy;if(xx<0||xx>=w||yy>=h)continue;for(let k=0;k<3;k++)data[(yy*w+xx)*4+k]+= (data[i*4+k]-rgb[v][k])*f}}}postMessage({cells,progress:100})}catch(e){postMessage({error:e.message})}};
